    out = []
    for row in rows:
        values = row if isinstance(row, tuple) else (row,)
        bound = dict(zip([n.strip() for n in names], values, strict=True))
        label = ",".join(repr(v) for v in values)
        out.append((f"{name}[{label}]", _bind(func, bound)))
    return out


